CREATE OR REPLACE FUNCTION public.admin_create_hero_upload(p_admin_id uuid, p_file_name text, p_mime_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_token uuid := gen_random_uuid();
  v_mime text := lower(trim(coalesce(p_mime_type, '')));
  v_ext text;
  v_object_name text;
  v_expires_at timestamptz := now() + interval '15 minutes';
begin
  if p_admin_id is null or not public.meshwar_is_admin(p_admin_id) then
    raise exception 'not authorized';
  end if;

  v_ext := case v_mime
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    when 'image/gif' then 'gif'
    when 'video/mp4' then 'mp4'
    when 'video/webm' then 'webm'
    when 'video/quicktime' then 'mov'
    else null
  end;

  if v_ext is null then
    raise exception 'unsupported hero media mime type: %', v_mime;
  end if;

  -- Keep only live tickets; uploaded objects themselves remain immutable because
  -- CMS uses unique names with upsert=false and no UPDATE storage policy exists.
  delete from public.hero_upload_tokens where expires_at <= now();

  v_object_name := 'hero/' || v_token::text || '.' || v_ext;

  insert into public.hero_upload_tokens(token, admin_id, object_name, mime_type, expires_at)
  values (v_token, p_admin_id, v_object_name, v_mime, v_expires_at);

  return jsonb_build_object(
    'bucket', 'site-hero-media',
    'path', v_object_name,
    'mime_type', v_mime,
    'expires_at', v_expires_at,
    'max_bytes', 104857600,
    'original_name', left(coalesce(p_file_name, ''), 255)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_site_settings(p_admin_id text, p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_admin_id is null or btrim(p_admin_id) = '' then
    raise exception 'adminId is required';
  end if;

  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'site_settings payload must be a JSON object';
  end if;

  if not exists (
    select 1
    from public.employees e
    where e.id::text = btrim(p_admin_id)
      and lower(btrim(coalesce(e.role::text, ''))) in ('admin', 'أدمن', 'ادمن')
      and coalesce(e.is_active, true) = true
  ) then
    raise exception 'Not authorized to manage site settings';
  end if;

  insert into public.settings (key, value, updated_at)
  values ('site_settings', p_value, now())
  on conflict (key) do update
    set value = excluded.value,
        updated_at = now();

  return true;
end;
$function$
